import{_ as a,o,c as t,ae as r}from"./chunks/framework.qNV68s4p.js";const m=JSON.parse('{"title":"Platform Support","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platform-support.md","filePath":"guide/platform-support.md","lastUpdated":1776332384000}'),i={name:"guide/platform-support.md"};function l(d,e,n,s,p,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="platform-support" tabindex="-1">Platform Support <a class="header-anchor" href="#platform-support" aria-label="Permalink to &quot;Platform Support&quot;">​</a></h1><p>SweetEditor targets multiple Compose Multiplatform platforms.</p><h2 id="supported-targets" tabindex="-1">Supported Targets <a class="header-anchor" href="#supported-targets" aria-label="Permalink to &quot;Supported Targets&quot;">​</a></h2><ul><li>Android</li><li>iOS</li><li>JVM Desktop</li><li>JS</li><li>Wasm</li></ul><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><ul><li><code>commonMain</code>: shared APIs, editor models, protocol decoding, controller logic</li><li><code>androidMain</code>: Android platform bridges</li><li><code>iosMain</code>: iOS platform bridges</li><li><code>jvmMain</code>: Desktop/JVM platform bridges</li><li><code>webMain</code>: web-specific platform code</li></ul><h2 id="platform-notes" tabindex="-1">Platform Notes <a class="header-anchor" href="#platform-notes" aria-label="Permalink to &quot;Platform Notes&quot;">​</a></h2><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><ul><li>IME and text input are integrated through Android platform hooks</li><li>Compose UI hosts the editor and bridges gestures into the native editor model</li></ul><h3 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h3><ul><li>iOS bridge code lives in the dedicated iOS source set</li><li>Native lifecycle and rendering coordination are handled in the Kotlin wrapper layer</li></ul><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><ul><li>Mouse, wheel, keyboard, popup, and inline suggestion interaction are available</li><li>Desktop-specific wheel normalization is handled at the platform layer</li></ul><h3 id="web-wasm" tabindex="-1">Web / Wasm <a class="header-anchor" href="#web-wasm" aria-label="Permalink to &quot;Web / Wasm&quot;">​</a></h3><ul><li>Supported as target outputs in the wrapper layer</li><li>Depending on runtime environment, some platform interactions may continue to evolve</li></ul><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Keep shared editor logic in <code>commonMain</code> and isolate platform-specific behavior in the corresponding source set.</p>',17)])])}const h=a(i,[["render",l]]);export{m as __pageData,h as default};
